export type BookingRecord = { id: number; seats: number };

export type BookingState =
  | { step: 'draft' }
  | { step: 'pending'; record: BookingRecord }
  | { step: 'cancelled'; record: BookingRecord; reason: string };

export function describe(state: BookingState): string {
  return 'Booking #' + state.record.id;
}

import { describe } from '../src/state.ts';
import type { BookingRecord } from '../src/state.ts';
declare const rec: BookingRecord;
describe({ step: 'draft', record: rec }); // expect TS2353

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { describe } from '../src/state.ts';

const rec = { id: 7, seats: 30 };
test('draft', () => assert.equal(describe({ step: 'draft' }), 'Draft'));
test('pending', () => assert.equal(describe({ step: 'pending', record: rec }), 'Pending #7'));
test('cancelled', () => assert.equal(describe({ step: 'cancelled', record: rec, reason: 'exam' }), 'Cancelled #7: exam'));

