export type BookingRecord = { id: number; seats: number };

export type BookingState =
  | { step: 'draft' }
  | { step: 'pending'; record: BookingRecord }
  | { step: 'confirmed'; record: BookingRecord };
export type ActiveState = { step: 'pending'; record: BookingRecord } | { step: 'confirmed'; record: BookingRecord };

export function isActive(s: BookingState): boolean {
  return s.step === 'pending' || s.step === 'confirmed';
}

import { isActive } from '../src/active.ts';
import type { BookingState } from '../src/active.ts';

export function idOf(s: BookingState): number | null {
  if (isActive(s)) return s.record.id; // the predicate must narrow s here
  return null;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { idOf } from '../kiem/dung.ts';

const rec = { id: 7, seats: 30 };
test('active', () => assert.equal(idOf({ step: 'pending', record: rec }), 7));
test('not active', () => assert.equal(idOf({ step: 'draft' }), null));

