export type BookingRecord = { id: number; seats: number };

export type BookingState =
  | { step: 'draft' }
  | { step: 'invalid'; code: string }
  | { step: 'confirmed'; record: BookingRecord };

export function recordOf(state: BookingState): BookingRecord | null {
  return state.record;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { recordOf } from '../src/record.ts';

const rec = { id: 7, seats: 30 };
test('has record', () => assert.deepEqual(recordOf({ step: 'confirmed', record: rec }), rec));
test('draft', () => assert.equal(recordOf({ step: 'draft' }), null));
test('invalid', () => assert.equal(recordOf({ step: 'invalid', code: 'X' }), null));

